package com.interview.ood.q040_payment_wallet.solution;

import java.math.BigDecimal;
import java.time.Instant;

// Value Object — immutable record of a credit or debit.
// transactionId = idempotency key (UUID generated by caller).
//   In prod: client generates UUID before HTTP call; on network retry it re-sends same UUID.
//   WalletService checks transactionExists(transactionId) before applying debit — safe replay.
// Append-only: no UPDATE or DELETE on WalletTransaction rows.
//   In prod (AWS): DynamoDB Streams → Lambda → S3 WORM (Object Lock, COMPLIANCE mode) for audit.
public record WalletTransaction(
        String transactionId,
        WalletId walletId,
        TransactionType type,
        BigDecimal amount,
        Instant createdAt
) {}
